CREATE TABLE "Service" (
  "id" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "slug" TEXT NOT NULL,
  "category" TEXT NOT NULL DEFAULT 'ICT & Electrical',
  "description" TEXT NOT NULL DEFAULT '',
  "homeDescription" TEXT NOT NULL DEFAULT '',
  "imageUrl" TEXT NOT NULL DEFAULT '',
  "icon" TEXT NOT NULL DEFAULT 'Wrench',
  "whatsappMessage" TEXT NOT NULL DEFAULT '',
  "intro" TEXT NOT NULL DEFAULT '',
  "detailDescription" TEXT NOT NULL DEFAULT '',
  "detailItems" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
  "sortOrder" INTEGER NOT NULL DEFAULT 0,
  "isActive" BOOLEAN NOT NULL DEFAULT true,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "Service_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "Service_slug_key" ON "Service"("slug");
CREATE INDEX "Service_title_idx" ON "Service"("title");
CREATE INDEX "Service_sortOrder_idx" ON "Service"("sortOrder");
CREATE INDEX "Service_isActive_sortOrder_idx" ON "Service"("isActive", "sortOrder");

INSERT INTO "Service" ("id","title","slug","category","description","homeDescription","imageUrl","icon","whatsappMessage","intro","detailDescription","detailItems","sortOrder","isActive","updatedAt") VALUES
('service-electrical-wiring','Electrical Wiring & Installation','electrical-wiring-and-installation','Electrical solutions','Discuss electrical wiring, installations, fittings and practical solutions for your home, office or business premises.','Safe and professional electrical services.','/images/Complete%20Electrical%2C%20CCTV%20%26%20Phone%20Repair%20Services-3.png','Zap','Hello Abdul ICT & Electrical Solutions, I would like a quotation for Electrical Wiring & Installation. Please let me know what details you need.','Practical electrical installation support for homes, offices, shops and other business premises.','Talk to us about your electrical installation needs. We can discuss your space, the work required and the best next step before a visit or quotation.',ARRAY['Electrical wiring and installation enquiries','Lighting, switches, sockets and fittings','Planning support for home and business spaces','Discussing safety needs and installation requirements'],1,true,CURRENT_TIMESTAMP),
('service-cctv-installation','CCTV Camera Installation','cctv-camera-installation','Security solutions','Plan a security setup for your home or business, with advice on camera placement and installation requirements.','Secure your home and business.','/images/Electrical%2C%20Security%2C%20and%20Phone%20Repair%20Services-6.png','Camera','Hello Abdul ICT & Electrical Solutions, I am interested in CCTV Camera Installation. Please help me discuss my security needs.','Explore CCTV options to help monitor and protect your home, shop, office or business.','We can help you discuss camera placement, coverage, recording needs and installation requirements to plan a setup suited to your property.',ARRAY['CCTV installation enquiries for homes and businesses','Camera placement and coverage planning','Discussing recording and monitoring needs','Installation requirements and quotation enquiries'],2,true,CURRENT_TIMESTAMP),
('service-computer-repair','Computer Repair & Maintenance','computer-repair-and-maintenance','Computer support','Get your computer running smoothly again with diagnostics, troubleshooting, software support, upgrades and dependable maintenance.','Fix, optimize and keep your system running smoothly.','/images/ABDUL%20ICT%20Technical%20Services%20Showcase-5.png','Monitor','Hello Abdul ICT & Electrical Solutions, I would like to enquire about Computer Repair & Maintenance. Please advise me on the next steps.','Get help diagnosing computer problems and bringing your device back to dependable day-to-day use.','Whether your computer is slow, has software problems or needs maintenance, tell us what is happening so we can discuss suitable troubleshooting and repair options.',ARRAY['Computer diagnostics and troubleshooting','Software installation and configuration enquiries','Performance, maintenance and upgrade advice','Help with common computer issues'],3,true,CURRENT_TIMESTAMP),
('service-phone-repair','Phone Repair, Flashing & Unlocking','phone-repair-flashing-and-unlocking','Phone support','Get help with phone software issues, flashing, unlocking and hardware troubleshooting across supported phone brands.','All phone brands, software and hardware solutions.','/images/ABDUL%20ICT%20Services%20in%20Action-4.png','Smartphone','Hello Abdul ICT & Electrical Solutions, I need help with Phone Repair, Flashing & Unlocking. Please advise me on the next steps.','Get advice on phone software issues, supported flashing and unlocking requests, and hardware troubleshooting.','Share your phone brand and model, the issue you are experiencing and any error messages. We can then discuss possible next steps and availability.',ARRAY['Phone troubleshooting and repair enquiries','Software flashing support for supported devices','Unlocking enquiries where supported and authorised','Advice for common hardware and software issues'],4,true,CURRENT_TIMESTAMP),
('service-phone-accessories','Phone Spares & Accessories','phone-spares-and-accessories','Accessories','Ask us about phone replacement parts, chargers, cables, audio accessories and everyday essentials for your devices.','Original parts and quality accessories.','/images/Electrical%2C%20CCTV%2C%20and%20Phone%20Repair%20Services-1.png','Headphones','Hello Abdul ICT & Electrical Solutions, I am looking for Phone Spares & Accessories. Please share availability and prices.','Find out about phone parts and useful accessories for charging, connectivity and everyday use.','Tell us your phone brand and model, or the accessory you need, so we can help you check availability and current pricing.',ARRAY['Phone spares and replacement-part enquiries','Chargers, cables and adapters','Audio accessories and everyday essentials','Availability and price confirmation before purchase'],5,true,CURRENT_TIMESTAMP),
('service-computer-training','Computer Training','computer-training','Practical digital skills','Build practical digital skills through guided computer lessons, office applications, productivity tools and IT learning.','Build your skills for a brighter future.','/images/service-computer-training.svg','GraduationCap','Hello Abdul ICT & Electrical Solutions, I would like to enquire about Computer Training courses, schedules and fees.','Build confidence with practical computer skills for learning, work and everyday digital tasks.','Discuss your current experience and learning goals with us. We can help you enquire about suitable training topics, schedules and fees.',ARRAY['Computer basics and digital literacy','Windows and office productivity applications','Internet, email and safe online practices','Enquiries about hardware, design and web skills'],6,true,CURRENT_TIMESTAMP)
ON CONFLICT ("slug") DO NOTHING;
